          body: JSON.stringify({ name: input.value }),
        });
        projects.push(project);
        drawProjects();
        input.value = '';
        input.focus();
      } catch (error) { showError(error); }
      finally { submit.disabled = false; }
    });
  }
  app.setAttribute('aria-busy', 'false');
}

